from pathlib import Path
import argparse
import hashlib
import html
import json
import re
import shutil
import struct

ROOT = Path(__file__).resolve().parents[1]
PUBLIC = ROOT / 'public'
EVIDENCE = ROOT / 'docs/validation/site-v1.18'
CANDIDATE = ROOT / 'docs/validation/v1.18/candidates/final-art-h/candidate.json'
NATIVE = ROOT / 'docs/validation/v1.18/native-fresh-h/final-art-h-six-languages'
LEVELS = [1, 3, 6, 10]
POSES = ['Front', 'Back', 'Left', 'Right', 'Walking · front', 'Walking · back', 'Walking · left', 'Walking · right', 'Jump', 'Landing', 'Hug', 'Crouch', 'Happy', 'Sad', 'Surprised', 'Thinking', 'Calm', 'Ready', 'Guard', 'Proud']


def sha(path): return hashlib.sha256(path.read_bytes()).hexdigest()
def compact(value): return json.dumps(value, ensure_ascii=False, separators=(',', ':')) + '\n'
def esc(value): return html.escape(str(value), quote=True)
def bilingual(fr, en): return f'<span data-lang="fr" lang="fr">{fr}</span><span data-lang="en" lang="en" hidden>{en}</span>'


def picture(key, alt_fr, alt_en, eager=False):
    return f'<img src="assets/screenshots/v1.18/{key}-fr.png" data-screenshot-fr="assets/screenshots/v1.18/{key}-fr.png" data-screenshot-en="assets/screenshots/v1.18/{key}-en.png" alt="{esc(alt_fr)}" data-alt-fr="{esc(alt_fr)}" data-alt-en="{esc(alt_en)}" width="1080" height="2400" decoding="async" ' + ('fetchpriority="high"' if eager else 'loading="lazy"') + '>'


def page(release, roster):
    w = bilingual
    version = release['version']; mb = release['bytes'] / 1e6
    download = esc(release['downloadUrl'])
