def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument('--artifact-commit', help='Immutable 40-character source/artifact commit, when assigned by publication owner')
    p.add_argument('--download-url', default='/releases/luma-drift-1.18.0-prototype1.apk')
    p.add_argument('--lab-download-url', default='/releases/luma-drift-1.18.0-sandbox-prototype1.apk')
    p.add_argument('--check-only', action='store_true')
    args = p.parse_args()
    assert args.artifact_commit is None or re.fullmatch('[a-f0-9]{40}', args.artifact_commit)
    for url in (args.download_url, args.lab_download_url): assert re.fullmatch(r'/releases/[A-Za-z0-9.-]+\.apk', url)
    candidate = json.loads(CANDIDATE.read_text()); production = candidate['apks']['production']; lab = candidate['apks']['lab']
    frozen = json.loads((CANDIDATE.parent/'source-inputs-sha256.json').read_text())
    for entry in (production, lab): assert sha(Path(entry['path'])) == entry['sha256'] and Path(entry['path']).stat().st_size == entry['bytes']
    native = json.loads((NATIVE / 'report.json').read_text())
    assert native['passed'] and native['native']['passed'] and native['apk_sha256'] == production['sha256']
    release = {'schemaVersion':1, 'version':production['version'], 'versionCode':25, 'candidate':'1.18 H', 'applicationId':'com.androidhit.lumadrift', 'sha256':production['sha256'], 'bytes':production['bytes'], 'downloadUrl':args.download_url, 'labDownloadUrl':args.lab_download_url, 'labSha256':lab['sha256'], 'labBytes':lab['bytes'], 'artifactCommit':args.artifact_commit, 'publicationState':'prepared', 'configuration':{'testAds':True,'realCheckout':False,'paidPremiumDraws':False}, 'limits':['wearable attachments provisional','no global apparel fit qualification','no physical-phone or retention qualification']}
    pending, captures, sheets, roster = [], [], [], []
